/// The server side of the LDAP directory gateway (`@better-iam/ldap`): each tenant can publish its directory under
/// a base DN of its own, so applications that only speak LDAP (VPNs, NAS devices, CI servers, wikis) look people
/// and groups up and check passwords against Better IAM. The gateway decodes LDAP; this module holds the settings,
/// the deployment-wide base DN index, and the directory view a bound account may read.
/// TODO(port): a union or intersection type in TypeScript; JSON until ported.
pub type LdapUidMode = Value;

/// Builds the directory view of a tenant: active people, published groups and (optionally) service accounts.
pub async fn build_ldap_directory(
    ctx: &Arc<ServerContext>,
    tx: &Store,
    tenant: &better_iam_core::Tenant,
    settings: &crate::ldap::LdapSettings,
    self_: Option<&better_iam_core::AuthenticatedPrincipal>,
) -> IamResult<crate::ldap::LdapDirectory> {
    Err(not_ported("ldap.ts buildLdapDirectory"))
}

